CREATE TYPE "UserRole" AS ENUM ('OWNER','ADMIN','MEMBER','VIEWER'); CREATE TYPE "Plan" AS ENUM ('FREE','STARTER','GROWTH','PRO','AGENCY','ENTERPRISE'); CREATE TYPE "LeadStatus" AS ENUM ('NEW','QUALIFIED','CONTACTED','REPLIED','WON','LOST'); CREATE TYPE "OpportunityStatus" AS ENUM ('OPEN','DISMISSED','CONVERTED');
CREATE TABLE "Organization" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"plan" "Plan" NOT NULL DEFAULT 'FREE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"emailVerifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Membership" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"role" "UserRole" NOT NULL DEFAULT 'MEMBER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Membership_userId_organizationId_key" ON "Membership"("userId","organizationId"); ALTER TABLE "Membership" ADD CONSTRAINT "Membership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Membership" ADD CONSTRAINT "Membership_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "Campaign" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"query" TEXT NOT NULL,"location" TEXT NOT NULL,"offer" TEXT NOT NULL,"maxResults" INTEGER NOT NULL DEFAULT 100,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Business" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"externalId" TEXT,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL,"category" TEXT,"address" TEXT,"phone" TEXT,"website" TEXT,"domain" TEXT,"rating" DOUBLE PRECISION,"reviews" INTEGER,"source" TEXT NOT NULL,"sourceUrl" TEXT,"status" "LeadStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Business_org_name_domain_key" ON "Business"("organizationId","normalizedName","domain"); ALTER TABLE "Campaign" ADD CONSTRAINT "Campaign_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Business" ADD CONSTRAINT "Business_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "Contact" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"name" TEXT,"title" TEXT,"email" TEXT,"phone" TEXT,"sourceUrl" TEXT,"confidence" DOUBLE PRECISION NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "WebsiteData" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE,"url" TEXT NOT NULL,"title" TEXT,"description" TEXT,"text" TEXT,"statusCode" INTEGER,"crawledAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Evidence" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"type" TEXT NOT NULL,"url" TEXT,"quote" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CompanyResearch" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE,"summary" TEXT,"decisionMakers" JSONB,"technology" JSONB,"signals" JSONB,"quality" INTEGER NOT NULL DEFAULT 0,"provider" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Opportunity" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "OpportunityStatus" NOT NULL DEFAULT 'OPEN',"confidence" DOUBLE PRECISION NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LeadScore" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE,"score" INTEGER NOT NULL,"reasons" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CrawlJob" ("id" TEXT PRIMARY KEY,"campaignId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"attempts" INTEGER NOT NULL DEFAULT 0,"error" TEXT,"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Integration" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"type" TEXT NOT NULL,"endpoint" TEXT NOT NULL,"secretEncrypted" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SyncEvent" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"integrationId" TEXT NOT NULL,"status" TEXT NOT NULL,"responseCode" INTEGER,"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UsageEvent" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"kind" TEXT NOT NULL,"units" INTEGER NOT NULL DEFAULT 1,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ApiKey" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"prefix" TEXT NOT NULL,"keyHash" TEXT NOT NULL UNIQUE,"lastUsedAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"entity" TEXT,"entityId" TEXT,"ip" TEXT,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IdempotencyKey" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"key" TEXT NOT NULL,"requestHash" TEXT NOT NULL,"responseJson" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "Contact" ADD CONSTRAINT "Contact_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WebsiteData" ADD CONSTRAINT "WebsiteData_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Evidence" ADD CONSTRAINT "Evidence_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CompanyResearch" ADD CONSTRAINT "CompanyResearch_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Opportunity" ADD CONSTRAINT "Opportunity_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LeadScore" ADD CONSTRAINT "LeadScore_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CrawlJob" ADD CONSTRAINT "CrawlJob_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Integration" ADD CONSTRAINT "Integration_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SyncEvent" ADD CONSTRAINT "SyncEvent_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SyncEvent" ADD CONSTRAINT "SyncEvent_integrationId_fkey" FOREIGN KEY ("integrationId") REFERENCES "Integration"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UsageEvent" ADD CONSTRAINT "UsageEvent_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ApiKey" ADD CONSTRAINT "ApiKey_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE UNIQUE INDEX "Idempotency_org_key" ON "IdempotencyKey"("organizationId","key");
CREATE INDEX "Evidence_businessId_idx" ON "Evidence"("businessId"); CREATE INDEX "Opportunity_businessId_status_idx" ON "Opportunity"("businessId","status"); CREATE INDEX "CrawlJob_campaignId_status_idx" ON "CrawlJob"("campaignId","status"); CREATE INDEX "UsageEvent_org_created_idx" ON "UsageEvent"("organizationId","createdAt"); CREATE INDEX "AuditLog_org_created_idx" ON "AuditLog"("organizationId","createdAt");
